use std::collections::HashSet;
fn hash(v:&[Op])->String{let mut h=Sha3_256::new();for o in v{for x in [o.kind as u64,o.q_control2.0,o.q_control1.0,o.q_target.0,o.c_target.0,o.c_condition.0,o.r_target.0]{h.update(x.to_le_bytes());}}format!("{:x}",h.finalize())}
fn product(a:Option<Id>,b:Option<Id>,d:&mut BoolDag)->Option<Id>{match(a,b){(Some(0),_)|(_,Some(0))=>Some(0),(Some(x),Some(y))=>Some(d.and(x,y)),_=>None}}
fn toggle(a:Option<Id>,b:Option<Id>,d:&mut BoolDag)->Option<Id>{match(a,b){(Some(x),Some(y))=>Some(d.xor(x,y)),_=>None}}
fn reachable(id:Id,d:&BoolDag,live:&HashMap<Id,usize>,complement:&HashMap<Id,usize>,seen:&mut HashSet<Id>,rows:&mut Vec<serde_json::Value>,missing:&mut Vec<Id>){if !seen.insert(id){return;}if seen.len()>4096{return;}if id<2{rows.push(serde_json::json!({"id":id,"kind":"Const","value":id==1}));return;}if let Some(&bit)=live.get(&id){rows.push(serde_json::json!({"id":id,"kind":"Live","bit":bit,"negated":false}));return;}if let Some(&bit)=complement.get(&id){rows.push(serde_json::json!({"id":id,"kind":"Live","bit":bit,"negated":true}));return;}
 let(kind,children,detail)=match &d.nodes[id as usize]{B::Input(x)=>("Input",vec![],Some(*x)),B::Mr(x)=>("Mr",vec![],Some(*x)),B::Not(a)=>("Not",vec![*a],None),B::And(a)=>("And",a.clone(),None),B::Xor(a,b)=>("Xor",vec![*a,*b],None),B::Ite(g,a,b)=>("Ite",vec![*g,*a,*b],None),B::Cut(_,a,b)=>("And",vec![*a,*b],None),B::Zero|B::One=>unreachable!()};if children.is_empty(){missing.push(id);}for &x in &children{reachable(x,d,live,complement,seen,rows,missing);}rows.push(serde_json::json!({"id":id,"kind":kind,"children":children,"origin":detail}));}
fn main(){let root=std::path::PathBuf::from(std::env::args().nth(1).unwrap());let source=root.parent().unwrap().join("product-classical-factors-refresh-20261019/parent4.ops.bin");let v=io::load_ops(source.to_str().unwrap());assert_eq!(hash(&v),"f64a9d8c59cdc89e9b683988da84eb34fa78c5a884f0324ce824e4c07a00fa53");let target=5387927usize;assert_eq!(v[target].kind,K::CCX);let nq=v.iter().flat_map(|o|[o.q_control1.0,o.q_control2.0,o.q_target.0]).filter(|&x|x!=NO).max().unwrap()as usize+1;let nb=v.iter().flat_map(|o|[o.c_target.0,o.c_condition.0]).filter(|&x|x!=NO).max().unwrap()as usize+1;let mut d=BoolDag::new();let mut q=vec![Some(0);nq];let mut c=vec![0;nb];for o in &v{if o.kind==K::AppendToRegister{if o.q_target.0!=NO{q[o.q_target.0 as usize]=None;}if o.c_target.0!=NO{c[o.c_target.0 as usize]=d.node(B::Input(o.c_target.0));}}}let(mut base,mut stack,mut events)=(1,vec![],0u64);let mut rng_origins=vec![];
for(i,o)in v.iter().enumerate(){if o.kind==K::PushCondition{stack.push(base);base=d.and(base,c[o.c_condition.0 as usize]);continue;}if o.kind==K::PopCondition{base=stack.pop().unwrap();continue;}let eff=if o.c_condition.0==NO{base}else{d.and(base,c[o.c_condition.0 as usize])};let(t,a,b,ct)=(o.q_target.0 as usize,o.q_control1.0 as usize,o.q_control2.0 as usize,o.c_target.0 as usize);
 if i==target{assert_eq!(eff,1);let choices:Vec<_>=[a,b].into_iter().filter_map(|x|q[x].map(|f|(x,f))).collect();assert_eq!(choices.len(),1);let(wire,function)=choices[0];let mut live=HashMap::new();let mut comp=HashMap::new();for(bit,&id)in c.iter().enumerate(){live.entry(id).or_insert(bit);if let B::Not(child)=d.nodes[id as usize]{comp.entry(child).or_insert(bit);}}
  let mut seen=HashSet::new();let mut nodes=vec![];let mut missing=vec![];reachable(function,&d,&live,&comp,&mut seen,&mut nodes,&mut missing);let fields=[o.kind as u64,o.q_control2.0,o.q_control1.0,o.q_target.0,o.c_target.0,o.c_condition.0,o.r_target.0];let result=serde_json::json!({"status":"SOURCE_BOUND_EXACT_CLASSICAL_CONTROL_EXPRESSION_NOT_A_SCORE","input_full_sha3_256":hash(&v),"input_pre_tail_sha3_256":hash(&v[..v.len()-96]),"input_pre_tail_count":v.len()-96,"target_source_op":target,"expected_gate_fields":fields,"classical_quantum_control":wire,"expression_root":function,"root_constant":if function<2{Some(function==1)}else{None},"live_same_bit":live.get(&function),"live_complement_bit":comp.get(&function),"guard_proved_true":true,"captured_scope_depth":stack.len(),"expression_nodes":nodes,"distinct_nodes_visited":seen.len(),"missing_variable_nodes":missing,"within_4096_node_bound":seen.len()<=4096,"bool_nodes":d.nodes.len(),"bool_cuts":d.cuts,"proof_invariant":"Every Some(q) is an exact Boolean function of classical input and MR variables; all quantum-dependent values are None. Live classical roots use the same immutable namespace.","scope":"No rewrite, statistical gate, nonce or resource score."});std::fs::write(root.join("EXPRESSION.json"),serde_json::to_string_pretty(&result).unwrap()).unwrap();println!("{}",result);return;}
 match o.kind{K::X=>q[t]=toggle(q[t],Some(eff),&mut d),K::CX=>{let p=product(Some(eff),q[a],&mut d);q[t]=toggle(q[t],p,&mut d);},K::CCX=>{let p=product(q[a],q[b],&mut d);let p=product(Some(eff),p,&mut d);q[t]=toggle(q[t],p,&mut d);},K::R|K::Hmr=>{q[t]=if eff==1{Some(0)}else if let Some(x)=q[t]{let ne=d.not(eff);Some(d.and(x,ne))}else{None};if o.kind==K::Hmr{let fresh=d.node(B::Mr(events));c[ct]=d.select(c[ct],fresh,eff);}rng_origins.push(i);events+=1;},K::Swap=>{let(x,y)=(q[a],q[t]);if eff==1{q[a]=y;q[t]=x;}else if eff!=0{if let(Some(x),Some(y))=(x,y){q[a]=Some(d.select(x,y,eff));q[t]=Some(d.select(y,x,eff));}else{q[a]=None;q[t]=None;}}},K::BitInvert=>c[ct]=d.xor(c[ct],eff),K::BitStore0=>c[ct]=d.select(c[ct],0,eff),K::BitStore1=>c[ct]=d.select(c[ct],1,eff),_=>{}}
}panic!("target not reached");}
